import { getPosts } from '../lib/api';
import { cacheLife, cacheTag } from 'next/cache';

export default async function Home() {
  'use cache';
  cacheLife({
    revalidate: 3600,
    expire: 86400,
  });
  cacheTag('posts');

  const posts = await getPosts();

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>Author: {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  );
}
